insert into auth.users(id,email) values ('a07b0000-0000-4000-8000-000000000001','z07-owner@example.invalid'),('a07b0000-0000-4000-8000-000000000002','z07-other@example.invalid');
insert into private.profiles(id) values ('a07b0000-0000-4000-8000-000000000001'),('a07b0000-0000-4000-8000-000000000002');
create temp table z07_articles(n int primary key,id uuid,revision uuid);insert into z07_articles select i,gen_random_uuid(),gen_random_uuid() from generate_series(1,26) i;
insert into private.articles(id,category_id) select z.id,c.id from z07_articles z cross join lateral(select id from private.categories limit 1)c;
insert into private.article_revisions(id,article_id,revision_number,title,micro_summary,full_paragraphs) select revision,id,1,'Simulación '||n,'Resumen','[]' from z07_articles;
insert into private.opinions(revision_id,character_id,body) select z.revision,c.id,'Prueba' from z07_articles z cross join private.characters c;
update private.articles a set current_revision_id=z.revision,status='published',published_at=now() from z07_articles z where a.id=z.id;
insert into private.article_user_state(user_id,article_id,omitted_at) select 'a07b0000-0000-4000-8000-000000000001',id,case when n=25 then '2021-01-01'::timestamptz else null end from z07_articles where n<=25;
insert into private.participations(user_id,article_id,revision_id,choice_kind,operation_id,payload_hash,confirmed_at) select 'a07b0000-0000-4000-8000-000000000001',id,revision,case when n<=4 then 'none' else 'voices' end,gen_random_uuid(),repeat('a',64),'2020-01-01'::timestamptz+n*interval '1 minute' from z07_articles where n<=24;
insert into private.participation_choices(participation_id,opinion_id) select p.id,o.id from private.participations p join z07_articles z on z.id=p.article_id join private.opinions o on o.revision_id=z.revision join private.characters c on c.id=o.character_id where p.user_id='a07b0000-0000-4000-8000-000000000001' and z.n between 5 and 24 and c.stable_key='rami';
insert into private.participation_choices(participation_id,opinion_id) select p.id,o.id from private.participations p join z07_articles z on z.id=p.article_id join private.opinions o on o.revision_id=z.revision join private.characters c on c.id=o.character_id where p.user_id='a07b0000-0000-4000-8000-000000000001' and z.n between 15 and 24 and c.stable_key='beatriz';
update private.participations p set confirmed_at='2020-01-01 00:23:00+00' from z07_articles z where p.article_id=z.id and z.n=24;
create temp table z07_page(cursor jsonb,ids uuid[]);grant select,insert on z07_page to authenticated;
grant select on z07_articles to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','a07b0000-0000-4000-8000-000000000001',true);
do $$ declare t jsonb;a jsonb;b jsonb;c jsonb;rami jsonb;beatriz jsonb;none_item jsonb;ids uuid[];more uuid[];begin
 t:=api.my_trends();select x into rami from jsonb_array_elements(t->'items') x where x->>'key'='rami';select x into none_item from jsonb_array_elements(t->'items') x where x->>'key'='none';select x into beatriz from jsonb_array_elements(t->'items') x where x->>'key'='beatriz';
 if (t->>'totalResponses')::int<>24 or (t->>'recentResponses')::int<>20 or (rami->>'totalPercent')::numeric<>83.3 or (rami->>'recentPercent')::numeric<>100 or (rami->>'differencePoints')::numeric<>16.7 or (beatriz->>'totalPercent')::numeric<>41.7 or (beatriz->>'recentPercent')::numeric<>50 or (beatriz->>'differencePoints')::numeric<>8.3 or (none_item->>'totalPercent')::numeric<>16.7 or (none_item->>'recentPercent')::numeric<>0 then raise exception 'Tendencias incorrectas: %',t;end if;
 a:=api.my_activity('all',null);if jsonb_array_length(a->'items')<>10 or not (a->>'hasMore')::boolean or a->'items'->0->>'status'<>'omitted' then raise exception 'Página inicial incorrecta';end if;
 select array_agg((x->>'articleId')::uuid) into ids from jsonb_array_elements(a->'items') x;b:=api.my_activity('all',a->'nextCursor');select array_agg((x->>'articleId')::uuid) into more from jsonb_array_elements(b->'items') x;if ids&&more or jsonb_array_length(b->'items')<>10 then raise exception 'Segunda página incorrecta';end if;
 c:=api.my_activity('all',b->'nextCursor');if jsonb_array_length(c->'items')<>5 or (c->>'hasMore')::boolean then raise exception 'Tercera página incorrecta';end if;
 if jsonb_array_length(api.my_activity('omitted',null)->'items')<>1 then raise exception 'Filtro omitidas incorrecto';end if;
 begin perform api.my_activity('responded',a->'nextCursor');raise exception 'Cursor de otro filtro aceptado';exception when invalid_parameter_value then null;end;
 if t::text like '%userId%' or a::text like '%userId%' then raise exception 'Identidad expuesta';end if;
end $$;
do $$ declare before_item jsonb;after_item jsonb;aid uuid;begin select id into aid from z07_articles where n=25;before_item:=api.my_activity('omitted',null)->'items'->0;perform api.omit_article(aid);perform api.access_results(aid,2);after_item:=api.my_activity('omitted',null)->'items'->0;if before_item->>'activityAt' is distinct from after_item->>'activityAt' then raise exception 'Lectura u omisión repetida alteró cronología';end if;end $$;
